#!/usr/bin/env node

const args = process.argv.slice(2);
const maxOptionIndex = args.indexOf('--max');
let max;

if (maxOptionIndex !== -1) {
  const value = args[maxOptionIndex + 1];
  max = Number(value);
  if (!value || !/^[0-9]+$/.test(value) || !Number.isSafeInteger(max) || max < 1) {
    console.error('--max must be a positive whole number.');
    process.exit(1);
  }
  args.splice(maxOptionIndex, 2);
}

if (args.length !== 1) {
  console.error('Provide one title.');
  process.exitCode = 1;
} else {
  const slug = args[0]
    .normalize('NFKD')
    .replace(/\p{M}/gu, '')
    .toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, '-')
    .replace(/^-|-$/g, '');

  if (!slug) {
    console.error('The title must contain a letter or number.');
    process.exitCode = 1;
  } else {
    const limited = max === undefined
      ? slug
      : Array.from(slug).slice(0, max).join('').replace(/-$/, '');
    console.log(limited);
  }
}
